// 動態組出 request body，end_month 為空字串時不帶入（ETL 自動用上個月）
const params = $input.item.json;
const body = {
  marketplace_id: params.marketplace_id,
  start_month: params.start_month,
};
if (params.end_month && params.end_month.trim() !== '') {
  body.end_month = params.end_month.trim();
}
return { body: JSON.stringify(body), ...params };

// 顯示 backfill 啟動摘要
const res = $input.item.json;
const months = res.months || [];
const est = res.estimated_minutes || 0;

console.log('=== Backfill Triggered ===');
console.log(`Months planned: ${res.months_planned}`);
console.log(`Period: ${res.start_month} → ${res.end_month}`);
console.log(`Estimated time: ~${est} minutes`);
console.log(`Monitor: http://localhost:8000/etl/traffic/history?limit=30`);
console.log('Months:', months.join(', '));

return {
  summary: `Backfill started: ${res.months_planned} months (${res.start_month} → ${res.end_month})`,
  estimated_minutes: est,
  monitor_url: 'http://localhost:8000/etl/traffic/history?limit=30',
  months: months,
};
